format_code:
hardware {
    pin led: Output = 2
}

machine Blinker {
    initial state off {
        enter { led.off() }
        on activate() -> on
    }

    state on {
        enter { led.on() }
        exit { log("leaving on state") }
        on deactivate() -> off
    }
}

system_graph.mermaid:
flowchart LR
    u_Blinker[["Blinker"]]
    p_led(["led"])
    s_activate{{"activate"}}
    s_log{{"log"}}
    s_deactivate{{"deactivate"}}
    u_Blinker -->|off, on| p_led
    u_Blinker -->|activate| s_activate
